package org.diy.liferecorder;
import android.content.*;import android.graphics.*;import android.view.*;import java.io.*;import java.util.*;
/** Cached RMS envelope of decoded PCM. No animation or generated peaks stands in for audio. */
final class WaveformView extends View {
 private static final java.util.concurrent.ExecutorService WORK=java.util.concurrent.Executors.newSingleThreadExecutor();
 private volatile float[] peaks=new float[0];private float progress;private volatile int generation;private String state="正在读取音轨…";private final Paint paint=new Paint(3);private final java.util.function.Consumer<Float> seek;
 WaveformView(Context c,java.util.function.Consumer<Float> target){super(c);seek=target;setContentDescription(AppLanguage.text(c,"音频波形，轻点跳转"));setFocusable(true);}
 void progress(float p){progress=Math.max(0,Math.min(1,p));invalidate();}
 void load(File file){load(Collections.singletonList(file),Collections.singletonList(1L));}
 void load(java.util.List<File> files,java.util.List<Long> durations){final int request=++generation;state="正在读取音轨…";WORK.execute(()->{try{ArrayList<float[]> parts=new ArrayList<>();long total=0;for(int i=0;i<files.size();i++){if(request!=generation)return;File file=files.get(i);parts.add(file.isFile()?envelope(getContext(),file,()->request!=generation):new float[160]);total+=Math.max(1,durations.get(i));}float[] merged=new float[160];long before=0;for(int i=0;i<parts.size();i++){long length=Math.max(1,durations.get(i));float[] part=parts.get(i);for(int k=0;k<160;k++){double pos=(k+.5)*total/160.0;if(pos>=before&&pos<before+length)merged[k]=part[Math.min(159,(int)((pos-before)*160/length))];}before+=length;}float max=.001f;for(float v:merged)max=Math.max(max,v);for(int i=0;i<merged.length;i++)merged[i]=(float)Math.sqrt(merged[i]/max);post(()->{if(request==generation){peaks=merged;state="";invalidate();}});}catch(Exception error){post(()->{if(request==generation){state="波形读取失败 · 可继续播放";invalidate();}});}});}
 static float[] envelope(Context c,File file,ProviderClient.Cancel cancel)throws Exception{String key=org.diy.lifecore.LocalSecurity.hex(java.security.MessageDigest.getInstance("SHA-256").digest((file.getPath()+":"+file.length()+":"+file.lastModified()).getBytes("UTF-8")));File cache=new File(c.getCacheDir(),"wave-"+key+".bin");float[] rms=new float[160];if(cache.length()==640){try(DataInputStream in=new DataInputStream(new FileInputStream(cache))){for(int i=0;i<160;i++)rms[i]=in.readFloat();}return rms;}File pcm=File.createTempFile("waveform-",".pcm",c.getCacheDir());try{SpeechRetention.decode(file,pcm,cancel);double[] sums=new double[160];long[] counts=new long[160];long samples=pcm.length()/2,at=0;try(InputStream in=new BufferedInputStream(new FileInputStream(pcm),65536)){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))>0){if(cancel.cancelled())throw new IOException("cancelled");for(int i=0;i+1<n;i+=2){int bin=(int)Math.min(159,at++*160/Math.max(1,samples));double value=(short)((bytes[i]&255)|((bytes[i+1]&255)<<8))/32768.0;sums[bin]+=value*value;counts[bin]++;}}}for(int i=0;i<160;i++)rms[i]=(float)Math.sqrt(sums[i]/Math.max(1,counts[i]));File tmp=File.createTempFile("wave-cache-",".part",c.getCacheDir());try{try(DataOutputStream out=new DataOutputStream(new FileOutputStream(tmp))){for(float v:rms)out.writeFloat(v);}tmp.renameTo(cache);}finally{tmp.delete();}return rms;}finally{pcm.delete();}}
 protected void onDetachedFromWindow(){generation++;super.onDetachedFromWindow();}
 protected void onDraw(Canvas c){super.onDraw(c);if(peaks.length==0){paint.setColor(0xff6e5e58);paint.setTextSize(12*getResources().getDisplayMetrics().scaledDensity);c.drawText(AppLanguage.text(getContext(),state),0,getHeight()/2f,paint);return;}int bars=Math.min(160,Math.max(32,getWidth()/6));float unit=getWidth()/(float)bars;paint.setStrokeWidth(Math.max(2,unit*.45f));paint.setStrokeCap(Paint.Cap.ROUND);for(int n=0;n<bars;n++){paint.setColor(n/(float)bars<=progress?0xffa44330:0xffd8c9bd);float peak=0;for(int j=n*160/bars;j<(n+1)*160/bars;j++)peak=Math.max(peak,peaks[j]);float h=Math.max(1,peak*getHeight()*.44f);c.drawLine(unit*(n+.5f),getHeight()/2f-h,unit*(n+.5f),getHeight()/2f+h,paint);}paint.setColor(0xffe87c63);paint.setStrokeWidth(2);c.drawLine(progress*getWidth(),0,progress*getWidth(),getHeight(),paint);}
 public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_UP){performClick();seek.accept(Math.max(0,Math.min(1,e.getX()/getWidth())));}return true;}
 public boolean performClick(){super.performClick();return true;}
}
